# -*- coding: utf-8 -*-
"""Class 10 Science Chapter 10 Simulators Dictionary"""

simulators = {
  "1": {
    "title": "Eye vs Camera Optics Studio",
    "description": "Compare biological ocular vision with mechanical camera optics. Observe how light rays refract through the cornea and crystalline lens to form a real, inverted image on the retinal screen.",
    "html": "\n            <div class=\"space-y-4\">\n                <div class=\"flex flex-wrap items-center justify-between gap-2 p-2.5 rounded-xl bg-slate-900/80 border border-slate-800 text-xs\">\n                    <div class=\"flex items-center gap-2\">\n                        <span class=\"text-slate-400\">Mode:</span>\n                        <button id=\"sim1_btn_eye\" onclick=\"sim1SetMode('eye')\" class=\"px-2.5 py-1 rounded-lg bg-amber-600 text-slate-950 font-bold\">Human Eye</button>\n                        <button id=\"sim1_btn_cam\" onclick=\"sim1SetMode('camera')\" class=\"px-2.5 py-1 rounded-lg bg-slate-800 hover:bg-slate-700 text-slate-300 font-medium\">Optical Camera</button>\n                    </div>\n                    <div class=\"flex items-center gap-2\">\n                        <span class=\"text-slate-400\">Illumination:</span>\n                        <input type=\"range\" id=\"sim1_light_slider\" min=\"20\" max=\"100\" value=\"70\" oninput=\"sim1Update()\" class=\"w-24 accent-amber-500\">\n                    </div>\n                </div>\n\n                <div class=\"relative w-full h-64 bg-slate-950 rounded-xl border border-slate-800 overflow-hidden flex items-center justify-center\">\n                    <canvas id=\"sim1_canvas\" width=\"600\" height=\"260\" class=\"w-full h-full\"></canvas>\n                </div>\n\n                <div class=\"grid grid-cols-2 sm:grid-cols-4 gap-2 text-center text-xs\">\n                    <div class=\"p-2 rounded-lg bg-slate-900/60 border border-slate-800\">\n                        <div class=\"text-slate-400 text-[10px]\">Front Refractor</div>\n                        <div id=\"sim1_val_front\" class=\"text-amber-400 font-bold\">Cornea (n=1.376)</div>\n                    </div>\n                    <div class=\"p-2 rounded-lg bg-slate-900/60 border border-slate-800\">\n                        <div class=\"text-slate-400 text-[10px]\">Aperture Control</div>\n                        <div id=\"sim1_val_aperture\" class=\"text-teal-400 font-bold\">Iris & Pupil</div>\n                    </div>\n                    <div class=\"p-2 rounded-lg bg-slate-900/60 border border-slate-800\">\n                        <div class=\"text-slate-400 text-[10px]\">Focusing Element</div>\n                        <div id=\"sim1_val_lens\" class=\"text-cyan-400 font-bold\">Crystalline Lens</div>\n                    </div>\n                    <div class=\"p-2 rounded-lg bg-slate-900/60 border border-slate-800\">\n                        <div class=\"text-slate-400 text-[10px]\">Image Screen</div>\n                        <div id=\"sim1_val_screen\" class=\"text-emerald-400 font-bold\">Retina (Real, Inverted)</div>\n                    </div>\n                </div>\n            </div>\n        "
  },
  "2": {
    "title": "Anatomy & Pupillary Light Reflex Studio",
    "description": "Interact with a cross-section of the human eyeball (diameter 2.3 cm). Adjust ambient ambient lighting to observe the pupillary reflex governed by the iris diaphragm.",
    "html": "\n            <div class=\"space-y-4\">\n                <div class=\"flex flex-wrap items-center justify-between gap-2 p-2.5 rounded-xl bg-slate-900/80 border border-slate-800 text-xs\">\n                    <div class=\"flex items-center gap-2\">\n                        <span class=\"text-slate-400\">Ambient Lighting:</span>\n                        <input type=\"range\" id=\"sim2_lux_slider\" min=\"10\" max=\"100\" value=\"50\" oninput=\"sim2Update()\" class=\"w-32 accent-amber-500\">\n                        <span id=\"sim2_lux_txt\" class=\"text-amber-400 font-mono font-bold\">50% (Normal)</span>\n                    </div>\n                    <button onclick=\"sim2ToggleLabels()\" id=\"sim2_btn_lbl\" class=\"px-2.5 py-1 rounded-lg bg-slate-800 hover:bg-slate-700 text-slate-300 font-medium\">Hide Anatomical Labels</button>\n                </div>\n\n                <div class=\"relative w-full h-64 bg-slate-950 rounded-xl border border-slate-800 overflow-hidden flex items-center justify-center\">\n                    <canvas id=\"sim2_canvas\" width=\"600\" height=\"260\" class=\"w-full h-full\"></canvas>\n                </div>\n\n                <div class=\"grid grid-cols-2 sm:grid-cols-4 gap-2 text-center text-xs\">\n                    <div class=\"p-2 rounded-lg bg-slate-900/60 border border-slate-800\">\n                        <div class=\"text-slate-400 text-[10px]\">Pupil Diameter</div>\n                        <div id=\"sim2_pupil_diam\" class=\"text-amber-400 font-mono font-bold\">4.0 mm</div>\n                    </div>\n                    <div class=\"p-2 rounded-lg bg-slate-900/60 border border-slate-800\">\n                        <div class=\"text-slate-400 text-[10px]\">Iris Muscle State</div>\n                        <div id=\"sim2_muscle_state\" class=\"text-teal-400 font-bold\">Balanced Tone</div>\n                    </div>\n                    <div class=\"p-2 rounded-lg bg-slate-900/60 border border-slate-800\">\n                        <div class=\"text-slate-400 text-[10px]\">Retinal Flux</div>\n                        <div id=\"sim2_flux_txt\" class=\"text-cyan-400 font-mono font-bold\">Optimal Safe</div>\n                    </div>\n                    <div class=\"p-2 rounded-lg bg-slate-900/60 border border-slate-800\">\n                        <div class=\"text-slate-400 text-[10px]\">Eyeball Metric</div>\n                        <div class=\"text-emerald-400 font-bold\">2.3 cm Spherical</div>\n                    </div>\n                </div>\n            </div>\n        "
  },
  "3": {
    "title": "Retina Photoreceptor Transducer Studio",
    "description": "Explore the cellular architecture of the retina. Compare night-vision Rod cells (~120M) with daylight color-vision Cone cells (~6M) and observe signal transduction into the optic nerve.",
    "html": "\n            <div class=\"space-y-4\">\n                <div class=\"flex flex-wrap items-center justify-between gap-2 p-2.5 rounded-xl bg-slate-900/80 border border-slate-700 text-xs\">\n                    <div class=\"flex items-center gap-2\">\n                        <span class=\"text-slate-400\">Illumination Level:</span>\n                        <button id=\"sim3_btn_dim\" onclick=\"sim3SetMode('dim')\" class=\"px-2.5 py-1 rounded-lg bg-slate-800 hover:bg-slate-700 text-slate-300 font-medium\">Dim Light (Rods)</button>\n                        <button id=\"sim3_btn_bright\" onclick=\"sim3SetMode('bright')\" class=\"px-2.5 py-1 rounded-lg bg-amber-600 text-slate-950 font-bold\">Bright Daylight (Cones)</button>\n                    </div>\n                    <div class=\"flex items-center gap-2\">\n                        <span class=\"text-slate-400\">Color Filter:</span>\n                        <select id=\"sim3_color_select\" onchange=\"sim3Update()\" class=\"bg-slate-900 text-amber-400 px-2 py-0.5 rounded border border-slate-700\">\n                            <option value=\"white\">White Sunlight</option>\n                            <option value=\"red\">Red (650 nm)</option>\n                            <option value=\"green\">Green (530 nm)</option>\n                            <option value=\"blue\">Blue (450 nm)</option>\n                        </select>\n                    </div>\n                </div>\n\n                <div class=\"relative w-full h-64 bg-slate-950 rounded-xl border border-slate-800 overflow-hidden flex items-center justify-center\">\n                    <canvas id=\"sim3_canvas\" width=\"600\" height=\"260\" class=\"w-full h-full\"></canvas>\n                </div>\n\n                <div class=\"grid grid-cols-2 sm:grid-cols-4 gap-2 text-center text-xs\">\n                    <div class=\"p-2 rounded-lg bg-slate-900/60 border border-slate-800\">\n                        <div class=\"text-slate-400 text-[10px]\">Active Receptors</div>\n                        <div id=\"sim3_active_type\" class=\"text-amber-400 font-bold\">Cone Photoreceptors</div>\n                    </div>\n                    <div class=\"p-2 rounded-lg bg-slate-900/60 border border-slate-800\">\n                        <div class=\"text-slate-400 text-[10px]\">Acuity & Color</div>\n                        <div id=\"sim3_perception_txt\" class=\"text-teal-400 font-bold\">Trichromatic High Acuity</div>\n                    </div>\n                    <div class=\"p-2 rounded-lg bg-slate-900/60 border border-slate-800\">\n                        <div class=\"text-slate-400 text-[10px]\">Electrical Potential</div>\n                        <div id=\"sim3_potential_txt\" class=\"text-cyan-400 font-mono font-bold\">-40 mV (Transduced)</div>\n                    </div>\n                    <div class=\"p-2 rounded-lg bg-slate-900/60 border border-slate-800\">\n                        <div class=\"text-slate-400 text-[10px]\">Optic Nerve Output</div>\n                        <div id=\"sim3_nerve_output\" class=\"text-emerald-400 font-bold\">Neural Spike Stream</div>\n                    </div>\n                </div>\n            </div>\n        "
  },
  "4": {
    "title": "Power of Accommodation Studio",
    "description": "Adjust the target object distance from infinity down to 10 cm. Watch ciliary muscles contract to increase crystalline lens curvature, and detect the onset of eyestrain below 25 cm.",
    "html": "\n            <div class=\"space-y-4\">\n                <div class=\"flex flex-wrap items-center justify-between gap-2 p-2.5 rounded-xl bg-slate-900/80 border border-slate-800 text-xs\">\n                    <div class=\"flex items-center gap-2\">\n                        <span class=\"text-slate-400\">Object Distance (u):</span>\n                        <input type=\"range\" id=\"sim4_dist_slider\" min=\"10\" max=\"300\" value=\"100\" oninput=\"sim4Update()\" class=\"w-36 accent-amber-500\">\n                        <span id=\"sim4_dist_txt\" class=\"text-amber-400 font-mono font-bold\">100 cm</span>\n                    </div>\n                    <div class=\"flex items-center gap-1.5\">\n                        <button onclick=\"sim4SetDist(300)\" class=\"px-2 py-0.5 rounded bg-slate-800 text-slate-300 hover:text-white\">Infinity</button>\n                        <button onclick=\"sim4SetDist(25)\" class=\"px-2 py-0.5 rounded bg-slate-800 text-amber-400 font-bold hover:text-amber-300\">Near Point (25 cm)</button>\n                        <button onclick=\"sim4SetDist(12)\" class=\"px-2 py-0.5 rounded bg-slate-800 text-rose-400 hover:text-rose-300\">Strain (&lt;25 cm)</button>\n                    </div>\n                </div>\n\n                <div class=\"relative w-full h-64 bg-slate-950 rounded-xl border border-slate-800 overflow-hidden flex items-center justify-center\">\n                    <canvas id=\"sim4_canvas\" width=\"600\" height=\"260\" class=\"w-full h-full\"></canvas>\n                </div>\n\n                <div class=\"grid grid-cols-2 sm:grid-cols-4 gap-2 text-center text-xs\">\n                    <div class=\"p-2 rounded-lg bg-slate-900/60 border border-slate-800\">\n                        <div class=\"text-slate-400 text-[10px]\">Ciliary Muscle State</div>\n                        <div id=\"sim4_muscle_txt\" class=\"text-amber-400 font-bold\">Partially Contracted</div>\n                    </div>\n                    <div class=\"p-2 rounded-lg bg-slate-900/60 border border-slate-800\">\n                        <div class=\"text-slate-400 text-[10px]\">Lens Curvature</div>\n                        <div id=\"sim4_lens_thick\" class=\"text-teal-400 font-bold\">Moderate Bulge</div>\n                    </div>\n                    <div class=\"p-2 rounded-lg bg-slate-900/60 border border-slate-800\">\n                        <div class=\"text-slate-400 text-[10px]\">Focal Length (f)</div>\n                        <div id=\"sim4_focal_txt\" class=\"text-cyan-400 font-mono font-bold\">2.21 cm</div>\n                    </div>\n                    <div class=\"p-2 rounded-lg bg-slate-900/60 border border-slate-800\">\n                        <div class=\"text-slate-400 text-[10px]\">Retinal Focus Status</div>\n                        <div id=\"sim4_focus_status\" class=\"text-emerald-400 font-bold\">Sharp Focus</div>\n                    </div>\n                </div>\n            </div>\n        "
  },
  "5": {
    "title": "Myopia Optics & Concave Lens Correction Studio",
    "description": "Simulate near-sightedness caused by eyeball elongation or excessive corneal curvature. Observe rays focusing before the retina, and insert a corrective concave lens to restore sharp focus.",
    "html": "\n            <div class=\"space-y-4\">\n                <div class=\"flex flex-wrap items-center justify-between gap-2 p-2.5 rounded-xl bg-slate-900/80 border border-slate-800 text-xs\">\n                    <div class=\"flex items-center gap-2\">\n                        <span class=\"text-slate-400\">Myopic Far Point (d):</span>\n                        <input type=\"range\" id=\"sim5_fp_slider\" min=\"50\" max=\"250\" value=\"100\" oninput=\"sim5Update()\" class=\"w-28 accent-amber-500\">\n                        <span id=\"sim5_fp_txt\" class=\"text-amber-400 font-mono font-bold\">100 cm</span>\n                    </div>\n                    <div class=\"flex items-center gap-2\">\n                        <button id=\"sim5_toggle_lens\" onclick=\"sim5ToggleCorrection()\" class=\"px-3 py-1 rounded-lg bg-amber-600 text-slate-950 font-bold\">Apply Concave Lens</button>\n                    </div>\n                </div>\n\n                <div class=\"relative w-full h-64 bg-slate-950 rounded-xl border border-slate-800 overflow-hidden flex items-center justify-center\">\n                    <canvas id=\"sim5_canvas\" width=\"600\" height=\"260\" class=\"w-full h-full\"></canvas>\n                </div>\n\n                <div class=\"grid grid-cols-2 sm:grid-cols-4 gap-2 text-center text-xs\">\n                    <div class=\"p-2 rounded-lg bg-slate-900/60 border border-slate-800\">\n                        <div class=\"text-slate-400 text-[10px]\">Convergence Point</div>\n                        <div id=\"sim5_conv_txt\" class=\"text-rose-400 font-bold\">In Front of Retina</div>\n                    </div>\n                    <div class=\"p-2 rounded-lg bg-slate-900/60 border border-slate-800\">\n                        <div class=\"text-slate-400 text-[10px]\">Corrective Lens Type</div>\n                        <div id=\"sim5_lens_type\" class=\"text-teal-400 font-bold\">Diverging Concave</div>\n                    </div>\n                    <div class=\"p-2 rounded-lg bg-slate-900/60 border border-slate-800\">\n                        <div class=\"text-slate-400 text-[10px]\">Required Power (P)</div>\n                        <div id=\"sim5_power_txt\" class=\"text-cyan-400 font-mono font-bold\">-1.00 D</div>\n                    </div>\n                    <div class=\"p-2 rounded-lg bg-slate-900/60 border border-slate-800\">\n                        <div class=\"text-slate-400 text-[10px]\">Vision Acuity</div>\n                        <div id=\"sim5_acuity_txt\" class=\"text-amber-400 font-bold\">Blurred Distance</div>\n                    </div>\n                </div>\n            </div>\n        "
  },
  "6": {
    "title": "Hypermetropia Optics & Convex Lens Correction Studio",
    "description": "Simulate far-sightedness caused by a short eyeball or insufficient lens curvature. Rays converge behind the retina; insert a convex spectacle lens to bring the focal point forward onto the retina.",
    "html": "\n            <div class=\"space-y-4\">\n                <div class=\"flex flex-wrap items-center justify-between gap-2 p-2.5 rounded-xl bg-slate-900/80 border border-slate-800 text-xs\">\n                    <div class=\"flex items-center gap-2\">\n                        <span class=\"text-slate-400\">Receded Near Point (d'):</span>\n                        <input type=\"range\" id=\"sim6_np_slider\" min=\"35\" max=\"150\" value=\"75\" oninput=\"sim6Update()\" class=\"w-28 accent-amber-500\">\n                        <span id=\"sim6_np_txt\" class=\"text-amber-400 font-mono font-bold\">75 cm</span>\n                    </div>\n                    <div class=\"flex items-center gap-2\">\n                        <button id=\"sim6_toggle_lens\" onclick=\"sim6ToggleCorrection()\" class=\"px-3 py-1 rounded-lg bg-amber-600 text-slate-950 font-bold\">Apply Convex Lens</button>\n                    </div>\n                </div>\n\n                <div class=\"relative w-full h-64 bg-slate-950 rounded-xl border border-slate-800 overflow-hidden flex items-center justify-center\">\n                    <canvas id=\"sim6_canvas\" width=\"600\" height=\"260\" class=\"w-full h-full\"></canvas>\n                </div>\n\n                <div class=\"grid grid-cols-2 sm:grid-cols-4 gap-2 text-center text-xs\">\n                    <div class=\"p-2 rounded-lg bg-slate-900/60 border border-slate-800\">\n                        <div class=\"text-slate-400 text-[10px]\">Uncorrected Focus</div>\n                        <div id=\"sim6_conv_txt\" class=\"text-rose-400 font-bold\">Behind Retina</div>\n                    </div>\n                    <div class=\"p-2 rounded-lg bg-slate-900/60 border border-slate-800\">\n                        <div class=\"text-slate-400 text-[10px]\">Corrective Lens Type</div>\n                        <div id=\"sim6_lens_type\" class=\"text-teal-400 font-bold\">Converging Convex</div>\n                    </div>\n                    <div class=\"p-2 rounded-lg bg-slate-900/60 border border-slate-800\">\n                        <div class=\"text-slate-400 text-[10px]\">Required Power (P)</div>\n                        <div id=\"sim6_power_txt\" class=\"text-cyan-400 font-mono font-bold\">+2.67 D</div>\n                    </div>\n                    <div class=\"p-2 rounded-lg bg-slate-900/60 border border-slate-800\">\n                        <div class=\"text-slate-400 text-[10px]\">Reading Vision (25 cm)</div>\n                        <div id=\"sim6_acuity_txt\" class=\"text-amber-400 font-bold\">Uncorrected Blurry</div>\n                    </div>\n                </div>\n            </div>\n        "
  },
  "7": {
    "title": "Presbyopia & Bi-Focal Spectacle Studio",
    "description": "Examine age-related loss of accommodation and bi-focal lens optics. Switch between straight-ahead distant viewing (upper concave segment) and downward reading gaze (lower convex segment).",
    "html": "\n            <div class=\"space-y-4\">\n                <div class=\"flex flex-wrap items-center justify-between gap-2 p-2.5 rounded-xl bg-slate-900/80 border border-slate-800 text-xs\">\n                    <div class=\"flex items-center gap-2\">\n                        <span class=\"text-slate-400\">Gaze Direction:</span>\n                        <button id=\"sim7_btn_dist\" onclick=\"sim7SetGaze('distance')\" class=\"px-2.5 py-1 rounded-lg bg-amber-600 text-slate-950 font-bold\">Straight Ahead (Distance)</button>\n                        <button id=\"sim7_btn_near\" onclick=\"sim7SetGaze('reading')\" class=\"px-2.5 py-1 rounded-lg bg-slate-800 hover:bg-slate-700 text-slate-300 font-medium\">Downward (Reading)</button>\n                    </div>\n                    <div class=\"flex items-center gap-2\">\n                        <span class=\"text-slate-400\">Patient Age:</span>\n                        <input type=\"range\" id=\"sim7_age_slider\" min=\"40\" max=\"75\" value=\"55\" oninput=\"sim7Update()\" class=\"w-24 accent-amber-500\">\n                        <span id=\"sim7_age_txt\" class=\"text-amber-400 font-mono font-bold\">55 yrs</span>\n                    </div>\n                </div>\n\n                <div class=\"relative w-full h-64 bg-slate-950 rounded-xl border border-slate-800 overflow-hidden flex items-center justify-center\">\n                    <canvas id=\"sim7_canvas\" width=\"600\" height=\"260\" class=\"w-full h-full\"></canvas>\n                </div>\n\n                <div class=\"grid grid-cols-2 sm:grid-cols-4 gap-2 text-center text-xs\">\n                    <div class=\"p-2 rounded-lg bg-slate-900/60 border border-slate-800\">\n                        <div class=\"text-slate-400 text-[10px]\">Active Bi-Focal Zone</div>\n                        <div id=\"sim7_zone_txt\" class=\"text-amber-400 font-bold\">Upper Concave Segment</div>\n                    </div>\n                    <div class=\"p-2 rounded-lg bg-slate-900/60 border border-slate-800\">\n                        <div class=\"text-slate-400 text-[10px]\">Ciliary Muscle Tone</div>\n                        <div id=\"sim7_muscle_txt\" class=\"text-teal-400 font-bold\">Weakened Elasticity</div>\n                    </div>\n                    <div class=\"p-2 rounded-lg bg-slate-900/60 border border-slate-800\">\n                        <div class=\"text-slate-400 text-[10px]\">Lens Power Prescribed</div>\n                        <div id=\"sim7_rx_txt\" class=\"text-cyan-400 font-mono font-bold\">-1.50 D / +2.00 D</div>\n                    </div>\n                    <div class=\"p-2 rounded-lg bg-slate-900/60 border border-slate-800\">\n                        <div class=\"text-slate-400 text-[10px]\">Corneal Graft Window</div>\n                        <div class=\"text-emerald-400 font-bold\">4 to 6 hrs post-mortem</div>\n                    </div>\n                </div>\n            </div>\n        "
  },
  "8": {
    "title": "Prism Refraction & Deviation Goniometer",
    "description": "Trace monochromatic light through a triangular glass prism. Vary the prism angle (A) and angle of incidence (i) to measure angles of refraction, emergence (e), and deviation (D).",
    "html": "\n            <div class=\"space-y-4\">\n                <div class=\"flex flex-wrap items-center justify-between gap-2 p-2.5 rounded-xl bg-slate-900/80 border border-slate-800 text-xs\">\n                    <div class=\"flex items-center gap-2\">\n                        <span class=\"text-slate-400\">Angle of Incidence (i):</span>\n                        <input type=\"range\" id=\"sim8_i_slider\" min=\"25\" max=\"75\" value=\"48\" oninput=\"sim8Update()\" class=\"w-28 accent-amber-500\">\n                        <span id=\"sim8_i_txt\" class=\"text-amber-400 font-mono font-bold\">48\u00b0</span>\n                    </div>\n                    <div class=\"flex items-center gap-2\">\n                        <span class=\"text-slate-400\">Prism Angle (A):</span>\n                        <input type=\"range\" id=\"sim8_a_slider\" min=\"45\" max=\"75\" value=\"60\" oninput=\"sim8Update()\" class=\"w-24 accent-amber-500\">\n                        <span id=\"sim8_a_txt\" class=\"text-cyan-400 font-mono font-bold\">60\u00b0</span>\n                    </div>\n                </div>\n\n                <div class=\"relative w-full h-64 bg-slate-950 rounded-xl border border-slate-800 overflow-hidden flex items-center justify-center\">\n                    <canvas id=\"sim8_canvas\" width=\"600\" height=\"260\" class=\"w-full h-full\"></canvas>\n                </div>\n\n                <div class=\"grid grid-cols-2 sm:grid-cols-4 gap-2 text-center text-xs\">\n                    <div class=\"p-2 rounded-lg bg-slate-900/60 border border-slate-800\">\n                        <div class=\"text-slate-400 text-[10px]\">Angle of Emergence (e)</div>\n                        <div id=\"sim8_e_txt\" class=\"text-teal-400 font-mono font-bold\">48.2\u00b0</div>\n                    </div>\n                    <div class=\"p-2 rounded-lg bg-slate-900/60 border border-slate-800\">\n                        <div class=\"text-slate-400 text-[10px]\">Angle of Deviation (D)</div>\n                        <div id=\"sim8_d_txt\" class=\"text-amber-400 font-mono font-bold\">36.2\u00b0</div>\n                    </div>\n                    <div class=\"p-2 rounded-lg bg-slate-900/60 border border-slate-800\">\n                        <div class=\"text-slate-400 text-[10px]\">Sum Formula Check</div>\n                        <div id=\"sim8_sum_txt\" class=\"text-cyan-400 font-mono font-bold\">i + e = A + D</div>\n                    </div>\n                    <div class=\"p-2 rounded-lg bg-slate-900/60 border border-slate-800\">\n                        <div class=\"text-slate-400 text-[10px]\">Refractive Index (n)</div>\n                        <div class=\"text-emerald-400 font-mono font-bold\">1.50 (Crown Glass)</div>\n                    </div>\n                </div>\n            </div>\n        "
  },
  "9": {
    "title": "Prism Dispersion & VIBGYOR Spectrum Studio",
    "description": "Send a white sunlight beam through an optical prism (Activity 10.2). Observe how differential refractive indices fan out the beam into the 7 distinct spectral colors of VIBGYOR.",
    "html": "\n            <div class=\"space-y-4\">\n                <div class=\"flex flex-wrap items-center justify-between gap-2 p-2.5 rounded-xl bg-slate-900/80 border border-slate-800 text-xs\">\n                    <div class=\"flex items-center gap-2\">\n                        <span class=\"text-slate-400\">Light Source:</span>\n                        <button id=\"sim9_btn_white\" onclick=\"sim9SetSource('white')\" class=\"px-2.5 py-1 rounded-lg bg-amber-600 text-slate-950 font-bold\">White Sunlight</button>\n                        <button id=\"sim9_btn_mono\" onclick=\"sim9SetSource('mono')\" class=\"px-2.5 py-1 rounded-lg bg-slate-800 hover:bg-slate-700 text-slate-300 font-medium\">Monochromatic (Laser)</button>\n                    </div>\n                    <div class=\"flex items-center gap-2\">\n                        <span class=\"text-slate-400\">Beam Width:</span>\n                        <input type=\"range\" id=\"sim9_width_slider\" min=\"2\" max=\"15\" value=\"6\" oninput=\"sim9Update()\" class=\"w-24 accent-amber-500\">\n                    </div>\n                </div>\n\n                <div class=\"relative w-full h-64 bg-slate-950 rounded-xl border border-slate-800 overflow-hidden flex items-center justify-center\">\n                    <canvas id=\"sim9_canvas\" width=\"600\" height=\"260\" class=\"w-full h-full\"></canvas>\n                </div>\n\n                <div class=\"grid grid-cols-2 sm:grid-cols-4 gap-2 text-center text-xs\">\n                    <div class=\"p-2 rounded-lg bg-slate-900/60 border border-slate-800\">\n                        <div class=\"text-slate-400 text-[10px]\">Least Deviated Color</div>\n                        <div class=\"text-rose-400 font-bold\">Red (\u03bb \u2248 700 nm, v_max)</div>\n                    </div>\n                    <div class=\"p-2 rounded-lg bg-slate-900/60 border border-slate-800\">\n                        <div class=\"text-slate-400 text-[10px]\">Most Deviated Color</div>\n                        <div class=\"text-purple-400 font-bold\">Violet (\u03bb \u2248 400 nm, v_min)</div>\n                    </div>\n                    <div class=\"p-2 rounded-lg bg-slate-900/60 border border-slate-800\">\n                        <div class=\"text-slate-400 text-[10px]\">Angular Dispersion</div>\n                        <div id=\"sim9_disp_txt\" class=\"text-cyan-400 font-mono font-bold\">\u0394\u03b8 \u2248 1.85\u00b0</div>\n                    </div>\n                    <div class=\"p-2 rounded-lg bg-slate-800/60 border border-slate-800\">\n                        <div class=\"text-slate-400 text-[10px]\">Spectral Sequence</div>\n                        <div class=\"text-amber-300 font-bold tracking-wider\">V-I-B-G-Y-O-R</div>\n                    </div>\n                </div>\n            </div>\n        "
  },
  "10": {
    "title": "Newton Recombination Apparatus Studio",
    "description": "Recreate Isaac Newton's two-prism experiment (Figure 10.6). Toggle the second inverted identical prism to observe dispersed VIBGYOR rays recombining into a beam of pure white light.",
    "html": "\n            <div class=\"space-y-4\">\n                <div class=\"flex flex-wrap items-center justify-between gap-2 p-2.5 rounded-xl bg-slate-900/80 border border-slate-800 text-xs\">\n                    <div class=\"flex items-center gap-2\">\n                        <span class=\"text-slate-400\">Second Prism (P2):</span>\n                        <button id=\"sim10_toggle_p2\" onclick=\"sim10ToggleP2()\" class=\"px-3 py-1 rounded-lg bg-amber-600 text-slate-950 font-bold\">Inverted P2 Active</button>\n                    </div>\n                    <div class=\"flex items-center gap-2\">\n                        <span class=\"text-slate-400\">Prism Separation:</span>\n                        <input type=\"range\" id=\"sim10_sep_slider\" min=\"40\" max=\"150\" value=\"80\" oninput=\"sim10Update()\" class=\"w-28 accent-amber-500\">\n                    </div>\n                </div>\n\n                <div class=\"relative w-full h-64 bg-slate-950 rounded-xl border border-slate-800 overflow-hidden flex items-center justify-center\">\n                    <canvas id=\"sim10_canvas\" width=\"600\" height=\"260\" class=\"w-full h-full\"></canvas>\n                </div>\n\n                <div class=\"grid grid-cols-2 sm:grid-cols-4 gap-2 text-center text-xs\">\n                    <div class=\"p-2 rounded-lg bg-slate-900/60 border border-slate-800\">\n                        <div class=\"text-slate-400 text-[10px]\">Prism 1 Action</div>\n                        <div class=\"text-teal-400 font-bold\">Dispersion (White \u2192 VIBGYOR)</div>\n                    </div>\n                    <div class=\"p-2 rounded-lg bg-slate-900/60 border border-slate-800\">\n                        <div class=\"text-slate-400 text-[10px]\">Prism 2 Action</div>\n                        <div id=\"sim10_p2_action\" class=\"text-amber-400 font-bold\">Equal & Opposite Recombination</div>\n                    </div>\n                    <div class=\"p-2 rounded-lg bg-slate-900/60 border border-slate-800\">\n                        <div class=\"text-slate-400 text-[10px]\">Emergent Screen Beam</div>\n                        <div id=\"sim10_screen_txt\" class=\"text-cyan-400 font-bold\">Pure White Sunlight</div>\n                    </div>\n                    <div class=\"p-2 rounded-lg bg-slate-900/60 border border-slate-800\">\n                        <div class=\"text-slate-400 text-[10px]\">Physical Proof</div>\n                        <div class=\"text-emerald-400 font-bold\">Sunlight is 7-Color Blend</div>\n                    </div>\n                </div>\n            </div>\n        "
  },
  "11": {
    "title": "Rainbow Droplet Internal Optics Studio",
    "description": "Trace sunlight entering a spherical water droplet (Figure 10.8). Step through the three optical stages: front refraction/dispersion, back internal reflection, and emergence refraction at 40\u00b0 to 42\u00b0.",
    "html": "\n            <div class=\"space-y-4\">\n                <div class=\"flex flex-wrap items-center justify-between gap-2 p-2.5 rounded-xl bg-slate-900/80 border border-slate-800 text-xs\">\n                    <div class=\"flex items-center gap-2\">\n                        <span class=\"text-slate-400\">Ray Tracing Stage:</span>\n                        <button id=\"sim11_btn_all\" onclick=\"sim11SetStage('all')\" class=\"px-2.5 py-1 rounded-lg bg-amber-600 text-slate-950 font-bold\">Full Sequence</button>\n                        <button id=\"sim11_btn_1\" onclick=\"sim11SetStage('1')\" class=\"px-2 py-1 rounded-lg bg-slate-800 hover:bg-slate-700 text-slate-300\">1. Refract/Disperse</button>\n                        <button id=\"sim11_btn_2\" onclick=\"sim11SetStage('2')\" class=\"px-2 py-1 rounded-lg bg-slate-800 hover:bg-slate-700 text-slate-300\">2. Internal Reflect</button>\n                        <button id=\"sim11_btn_3\" onclick=\"sim11SetStage('3')\" class=\"px-2 py-1 rounded-lg bg-slate-800 hover:bg-slate-700 text-slate-300\">3. Emerge</button>\n                    </div>\n                </div>\n\n                <div class=\"relative w-full h-64 bg-slate-950 rounded-xl border border-slate-800 overflow-hidden flex items-center justify-center\">\n                    <canvas id=\"sim11_canvas\" width=\"600\" height=\"260\" class=\"w-full h-full\"></canvas>\n                </div>\n\n                <div class=\"grid grid-cols-2 sm:grid-cols-4 gap-2 text-center text-xs\">\n                    <div class=\"p-2 rounded-lg bg-slate-900/60 border border-slate-800\">\n                        <div class=\"text-slate-400 text-[10px]\">Red Light Emergence</div>\n                        <div class=\"text-rose-400 font-mono font-bold\">42.0\u00b0 (Outer Arc)</div>\n                    </div>\n                    <div class=\"p-2 rounded-lg bg-slate-900/60 border border-slate-800\">\n                        <div class=\"text-slate-400 text-[10px]\">Violet Emergence</div>\n                        <div class=\"text-purple-400 font-mono font-bold\">40.2\u00b0 (Inner Arc)</div>\n                    </div>\n                    <div class=\"p-2 rounded-lg bg-slate-900/60 border border-slate-800\">\n                        <div class=\"text-slate-400 text-[10px]\">Back Wall Physics</div>\n                        <div class=\"text-cyan-400 font-bold\">Total Internal Reflection (&gt;48.6\u00b0)</div>\n                    </div>\n                    <div class=\"p-2 rounded-lg bg-slate-900/60 border border-slate-800\">\n                        <div class=\"text-slate-400 text-[10px]\">Observer Geometry</div>\n                        <div class=\"text-emerald-400 font-bold\">Sun at Back, Rain Ahead</div>\n                    </div>\n                </div>\n            </div>\n        "
  },
  "12": {
    "title": "Atmospheric Refraction Gradient Studio",
    "description": "Visualize light propagating downward through atmospheric layers of increasing density. Observe how continuous refraction towards the normal curves light trajectories into downward-concave arcs.",
    "html": "\n            <div class=\"space-y-4\">\n                <div class=\"flex flex-wrap items-center justify-between gap-2 p-2.5 rounded-xl bg-slate-900/80 border border-slate-800 text-xs\">\n                    <div class=\"flex items-center gap-2\">\n                        <span class=\"text-slate-400\">Incident Angle (\u03b8):</span>\n                        <input type=\"range\" id=\"sim12_angle_slider\" min=\"15\" max=\"75\" value=\"45\" oninput=\"sim12Update()\" class=\"w-28 accent-amber-500\">\n                        <span id=\"sim12_angle_txt\" class=\"text-amber-400 font-mono font-bold\">45\u00b0</span>\n                    </div>\n                    <div class=\"flex items-center gap-2\">\n                        <span class=\"text-slate-400\">Atmosphere:</span>\n                        <button id=\"sim12_toggle_atm\" onclick=\"sim12ToggleAtmosphere()\" class=\"px-2.5 py-1 rounded-lg bg-amber-600 text-slate-950 font-bold\">Normal Atmosphere</button>\n                    </div>\n                </div>\n\n                <div class=\"relative w-full h-64 bg-slate-950 rounded-xl border border-slate-800 overflow-hidden flex items-center justify-center\">\n                    <canvas id=\"sim12_canvas\" width=\"600\" height=\"260\" class=\"w-full h-full\"></canvas>\n                </div>\n\n                <div class=\"grid grid-cols-2 sm:grid-cols-4 gap-2 text-center text-xs\">\n                    <div class=\"p-2 rounded-lg bg-slate-900/60 border border-slate-800\">\n                        <div class=\"text-slate-400 text-[10px]\">Upper Atmosphere (Vacuum)</div>\n                        <div class=\"text-teal-400 font-mono font-bold\">n = 1.00000</div>\n                    </div>\n                    <div class=\"p-2 rounded-lg bg-slate-900/60 border border-slate-800\">\n                        <div class=\"text-slate-400 text-[10px]\">Sea-Level Surface Air</div>\n                        <div class=\"text-cyan-400 font-mono font-bold\">n \u2248 1.00029</div>\n                    </div>\n                    <div class=\"p-2 rounded-lg bg-slate-900/60 border border-slate-800\">\n                        <div class=\"text-slate-400 text-[10px]\">Ray Path Geometry</div>\n                        <div id=\"sim12_path_txt\" class=\"text-amber-400 font-bold\">Curved Downward Arc</div>\n                    </div>\n                    <div class=\"p-2 rounded-lg bg-slate-900/60 border border-slate-800\">\n                        <div class=\"text-slate-400 text-[10px]\">Apparent Shift</div>\n                        <div class=\"text-emerald-400 font-bold\">Shifted Toward Zenith</div>\n                    </div>\n                </div>\n            </div>\n        "
  },
  "13": {
    "title": "Star Twinkling vs Planet Optics Studio",
    "description": "Simulate starlight from a point source traversing turbulent air eddies versus light from a nearby planet (extended source). See why stars twinkle while planetary brightness stays constant.",
    "html": "\n            <div class=\"space-y-4\">\n                <div class=\"flex flex-wrap items-center justify-between gap-2 p-2.5 rounded-xl bg-slate-900/80 border border-slate-800 text-xs\">\n                    <div class=\"flex items-center gap-2\">\n                        <span class=\"text-slate-400\">Source Selection:</span>\n                        <button id=\"sim13_btn_star\" onclick=\"sim13SetSource('star')\" class=\"px-2.5 py-1 rounded-lg bg-amber-600 text-slate-950 font-bold\">Distant Star (Point Source)</button>\n                        <button id=\"sim13_btn_planet\" onclick=\"sim13SetSource('planet')\" class=\"px-2.5 py-1 rounded-lg bg-slate-800 hover:bg-slate-700 text-slate-300 font-medium\">Planet (Extended Disk)</button>\n                    </div>\n                    <div class=\"flex items-center gap-2\">\n                        <span class=\"text-slate-400\">Turbulence:</span>\n                        <input type=\"range\" id=\"sim13_turb_slider\" min=\"1\" max=\"10\" value=\"5\" oninput=\"sim13Update()\" class=\"w-24 accent-amber-500\">\n                    </div>\n                </div>\n\n                <div class=\"relative w-full h-64 bg-slate-950 rounded-xl border border-slate-800 overflow-hidden flex items-center justify-center\">\n                    <canvas id=\"sim13_canvas\" width=\"600\" height=\"260\" class=\"w-full h-full\"></canvas>\n                </div>\n\n                <div class=\"grid grid-cols-2 sm:grid-cols-4 gap-2 text-center text-xs\">\n                    <div class=\"p-2 rounded-lg bg-slate-900/60 border border-slate-800\">\n                        <div class=\"text-slate-400 text-[10px]\">Source Geometry</div>\n                        <div id=\"sim13_geo_txt\" class=\"text-amber-400 font-bold\">Sub-Microscopic Point</div>\n                    </div>\n                    <div class=\"p-2 rounded-lg bg-slate-900/60 border border-slate-800\">\n                        <div class=\"text-slate-400 text-[10px]\">Apparent Position</div>\n                        <div id=\"sim13_pos_txt\" class=\"text-teal-400 font-bold\">Slightly Elevated & Fluctuating</div>\n                    </div>\n                    <div class=\"p-2 rounded-lg bg-slate-900/60 border border-slate-800\">\n                        <div class=\"text-slate-400 text-[10px]\">Luminous Intensity</div>\n                        <div id=\"sim13_lum_txt\" class=\"text-cyan-400 font-mono font-bold\">Twinkling Rapidly</div>\n                    </div>\n                    <div class=\"p-2 rounded-lg bg-slate-900/60 border border-slate-800\">\n                        <div class=\"text-slate-400 text-[10px]\">Averaging Effect</div>\n                        <div id=\"sim13_avg_txt\" class=\"text-emerald-400 font-bold\">No Cancellation (Single Ray)</div>\n                    </div>\n                </div>\n            </div>\n        "
  },
  "14": {
    "title": "Advanced Sunrise & Delayed Sunset Studio",
    "description": "Simulate solar rays grazing Earth's horizon (Figure 10.10). Atmospheric refraction bends rays when the Sun is 0.5\u00b0 below the horizon, extending perceived daily daylight by ~4 minutes.",
    "html": "\n            <div class=\"space-y-4\">\n                <div class=\"flex flex-wrap items-center justify-between gap-2 p-2.5 rounded-xl bg-slate-900/80 border border-slate-800 text-xs\">\n                    <div class=\"flex items-center gap-2\">\n                        <span class=\"text-slate-400\">Actual Solar Elevation:</span>\n                        <input type=\"range\" id=\"sim14_elev_slider\" min=\"-20\" max=\"20\" value=\"-5\" oninput=\"sim14Update()\" class=\"w-32 accent-amber-500\">\n                        <span id=\"sim14_elev_txt\" class=\"text-amber-400 font-mono font-bold\">-0.5\u00b0 (Below Horizon)</span>\n                    </div>\n                    <button id=\"sim14_toggle_anim\" onclick=\"sim14ToggleAnimation()\" class=\"px-2.5 py-1 rounded-lg bg-slate-800 hover:bg-slate-700 text-slate-300 font-medium\">Animate Solar Cycle</button>\n                </div>\n\n                <div class=\"relative w-full h-64 bg-slate-950 rounded-xl border border-slate-800 overflow-hidden flex items-center justify-center\">\n                    <canvas id=\"sim14_canvas\" width=\"600\" height=\"260\" class=\"w-full h-full\"></canvas>\n                </div>\n\n                <div class=\"grid grid-cols-2 sm:grid-cols-4 gap-2 text-center text-xs\">\n                    <div class=\"p-2 rounded-lg bg-slate-900/60 border border-slate-800\">\n                        <div class=\"text-slate-400 text-[10px]\">Physical Sun Position</div>\n                        <div id=\"sim14_true_txt\" class=\"text-rose-400 font-bold\">0.5\u00b0 Below Horizon</div>\n                    </div>\n                    <div class=\"p-2 rounded-lg bg-slate-900/60 border border-slate-800\">\n                        <div class=\"text-slate-400 text-[10px]\">Apparent Virtual Sun</div>\n                        <div id=\"sim14_app_txt\" class=\"text-amber-400 font-bold\">Visible Above Horizon</div>\n                    </div>\n                    <div class=\"p-2 rounded-lg bg-slate-900/60 border border-slate-800\">\n                        <div class=\"text-slate-400 text-[10px]\">Morning Time Shift</div>\n                        <div class=\"text-cyan-400 font-mono font-bold\">+2 Minutes Early</div>\n                    </div>\n                    <div class=\"p-2 rounded-lg bg-slate-900/60 border border-slate-800\">\n                        <div class=\"text-slate-400 text-[10px]\">Total Daily Daylight Bonus</div>\n                        <div class=\"text-emerald-400 font-bold\">~4 Full Minutes</div>\n                    </div>\n                </div>\n            </div>\n        "
  },
  "15": {
    "title": "Tyndall Effect Colloidal Scattering Studio",
    "description": "Compare a true molecular solution (e.g., salt in water) with a colloidal suspension (e.g., milk/mist). Observe how colloidal particles scatter photons to render the light beam pathway clearly visible.",
    "html": "\n            <div class=\"space-y-4\">\n                <div class=\"flex flex-wrap items-center justify-between gap-2 p-2.5 rounded-xl bg-slate-900/80 border border-slate-800 text-xs\">\n                    <div class=\"flex items-center gap-2\">\n                        <span class=\"text-slate-400\">Medium Type:</span>\n                        <button id=\"sim15_btn_colloid\" onclick=\"sim15SetMedium('colloid')\" class=\"px-2.5 py-1 rounded-lg bg-amber-600 text-slate-950 font-bold\">Colloid (Milk/Mist)</button>\n                        <button id=\"sim15_btn_true\" onclick=\"sim15SetMedium('true')\" class=\"px-2.5 py-1 rounded-lg bg-slate-800 hover:bg-slate-700 text-slate-300 font-medium\">True Solution (Salt Water)</button>\n                    </div>\n                    <div class=\"flex items-center gap-2\">\n                        <span class=\"text-slate-400\">Laser Intensity:</span>\n                        <input type=\"range\" id=\"sim15_laser_slider\" min=\"20\" max=\"100\" value=\"70\" oninput=\"sim15Update()\" class=\"w-24 accent-amber-500\">\n                    </div>\n                </div>\n\n                <div class=\"relative w-full h-64 bg-slate-950 rounded-xl border border-slate-800 overflow-hidden flex items-center justify-center\">\n                    <canvas id=\"sim15_canvas\" width=\"600\" height=\"260\" class=\"w-full h-full\"></canvas>\n                </div>\n\n                <div class=\"grid grid-cols-2 sm:grid-cols-4 gap-2 text-center text-xs\">\n                    <div class=\"p-2 rounded-lg bg-slate-900/60 border border-slate-800\">\n                        <div class=\"text-slate-400 text-[10px]\">Particle Size Range</div>\n                        <div id=\"sim15_size_txt\" class=\"text-amber-400 font-mono font-bold\">1 nm to 1000 nm</div>\n                    </div>\n                    <div class=\"p-2 rounded-lg bg-slate-900/60 border border-slate-800\">\n                        <div class=\"text-slate-400 text-[10px]\">Beam Path Visibility</div>\n                        <div id=\"sim15_vis_txt\" class=\"text-teal-400 font-bold\">Luminous Illuminated Cone</div>\n                    </div>\n                    <div class=\"p-2 rounded-lg bg-slate-900/60 border border-slate-800\">\n                        <div class=\"text-slate-400 text-[10px]\">Scattering Mechanism</div>\n                        <div class=\"text-cyan-400 font-bold\">Diffuse Tyndall Scattering</div>\n                    </div>\n                    <div class=\"p-2 rounded-lg bg-slate-900/60 border border-slate-800\">\n                        <div class=\"text-slate-400 text-[10px]\">Natural Analogue</div>\n                        <div class=\"text-emerald-400 font-bold\">Sunlight in Dusty Room / Canopy</div>\n                    </div>\n                </div>\n            </div>\n        "
  },
  "16": {
    "title": "Rayleigh Scattering & Sky Color Studio",
    "description": "Investigate Rayleigh's inverse-fourth-power law (I \u221d 1/\u03bb\u2074). Adjust the wavelength slider from violet (400 nm) to red (700 nm) to understand why the clear daytime sky is blue and danger signals are red.",
    "html": "\n            <div class=\"space-y-4\">\n                <div class=\"flex flex-wrap items-center justify-between gap-2 p-2.5 rounded-xl bg-slate-900/80 border border-slate-800 text-xs\">\n                    <div class=\"flex items-center gap-2\">\n                        <span class=\"text-slate-400\">Wavelength (\u03bb):</span>\n                        <input type=\"range\" id=\"sim16_wave_slider\" min=\"400\" max=\"700\" value=\"450\" oninput=\"sim16Update()\" class=\"w-32 accent-amber-500\">\n                        <span id=\"sim16_wave_txt\" class=\"text-blue-400 font-mono font-bold\">450 nm (Blue)</span>\n                    </div>\n                    <div class=\"flex items-center gap-2\">\n                        <button onclick=\"sim16SetPreset(400)\" class=\"px-2 py-0.5 rounded bg-slate-800 text-purple-400 hover:text-purple-300\">Violet</button>\n                        <button onclick=\"sim16SetPreset(460)\" class=\"px-2 py-0.5 rounded bg-slate-800 text-blue-400 font-bold hover:text-blue-300\">Blue Sky</button>\n                        <button onclick=\"sim16SetPreset(700)\" class=\"px-2 py-0.5 rounded bg-slate-800 text-rose-400 font-bold hover:text-rose-300\">Red Signal</button>\n                    </div>\n                </div>\n\n                <div class=\"relative w-full h-64 bg-slate-950 rounded-xl border border-slate-800 overflow-hidden flex items-center justify-center\">\n                    <canvas id=\"sim16_canvas\" width=\"600\" height=\"260\" class=\"w-full h-full\"></canvas>\n                </div>\n\n                <div class=\"grid grid-cols-2 sm:grid-cols-4 gap-2 text-center text-xs\">\n                    <div class=\"p-2 rounded-lg bg-slate-900/60 border border-slate-800\">\n                        <div class=\"text-slate-400 text-[10px]\">Relative Rayleigh Intensity</div>\n                        <div id=\"sim16_intensity_txt\" class=\"text-cyan-400 font-mono font-bold\">5.85 \u00d7 Baseline</div>\n                    </div>\n                    <div class=\"p-2 rounded-lg bg-slate-900/60 border border-slate-800\">\n                        <div class=\"text-slate-400 text-[10px]\">Blue vs Red Ratio</div>\n                        <div class=\"text-amber-400 font-mono font-bold\">(700/400)\u2074 \u2248 9.4\u00d7</div>\n                    </div>\n                    <div class=\"p-2 rounded-lg bg-slate-900/60 border border-slate-800\">\n                        <div class=\"text-slate-400 text-[10px]\">Sky Color Mode</div>\n                        <div id=\"sim16_sky_mode\" class=\"text-teal-400 font-bold\">Radiant Azure Dome</div>\n                    </div>\n                    <div class=\"p-2 rounded-lg bg-slate-900/60 border border-slate-800\">\n                        <div class=\"text-slate-400 text-[10px]\">Danger Signal Rationale</div>\n                        <div class=\"text-rose-400 font-bold\">Least Scattered by Fog/Smoke</div>\n                    </div>\n                </div>\n            </div>\n        "
  }
}
